import sys
from collections import deque

def bfs(n, edges, s):
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    dist = [-1] * (n + 1)
    dist[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 6
                queue.append(v)

    result = []
    for i in range(1, n + 1):
        if i != s:
            result.append(dist[i])
    return result

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        q = int(next(iterator))
    except StopIteration:
        return

    for _ in range(q):
        n = int(next(iterator))
        m = int(next(iterator))
        edges = []
        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            edges.append((u, v))
        s = int(next(iterator))

        result = bfs(n, edges, s)
        print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
